import sqlite3


class Queue:
    def __init__(self, path):
        self._db = sqlite3.connect(path, isolation_level=None)
        self._db.execute("PRAGMA journal_mode=WAL")

    def close(self):
        self._db.close()

    def _valid(self, value):
        return isinstance(value, str) and value != ""

    def add(self, id, title, owner, dependencies=None):
        if not (self._valid(id) and self._valid(title) and self._valid(owner)):
            raise ValueError("id, title and owner must be nonempty strings")
        deps = list(dependencies or [])
        if len(set(deps)) != len(deps):
            raise ValueError("duplicate dependencies")
        if id in deps:
            raise ValueError("self dependency")
        try:
            self._db.execute("BEGIN IMMEDIATE")
            row = self._db.execute("SELECT id FROM tasks WHERE id=?", (id,)).fetchone()
            if row is not None:
                raise ValueError("duplicate id")
            for dep in deps:
                if self._db.execute("SELECT id FROM tasks WHERE id=?", (dep,)).fetchone() is None:
                    raise KeyError("unknown dependency %s" % dep)
            self._db.execute("INSERT INTO tasks(id,title,owner,status) VALUES(?,?,?,?)", (id, title, owner, "pending"))
            for dep in deps:
                self._db.execute("INSERT INTO dependencies(task_id,depends_on) VALUES(?,?)", (id, dep))
            self._db.execute("INSERT INTO events(task_id,action,payload) VALUES(?,?,?)", (id, "add", None))
            self._db.execute("COMMIT")
        except Exception:
            self._db.execute("ROLLBACK")
            raise

    def get(self, id):
        row = self._db.execute("SELECT id,title,owner,status FROM tasks WHERE id=?", (id,)).fetchone()
        if row is None:
            raise KeyError(id)
        return {"id": row[0], "title": row[1], "owner": row[2], "status": row[3]}

    def list(self, owner=None, status=None):
        sql = "SELECT id,title,owner,status FROM tasks"
        clauses, params = [], []
        if owner is not None:
            clauses.append("owner=?"); params.append(owner)
        if status is not None:
            clauses.append("status=?"); params.append(status)
        if clauses:
            sql += " WHERE " + " AND ".join(clauses)
        sql += " ORDER BY id"
        return [{"id": r[0], "title": r[1], "owner": r[2], "status": r[3]}
                for r in self._db.execute(sql, params).fetchall()]

    def _deps_done(self, id):
        deps = [r[0] for r in self._db.execute("SELECT depends_on FROM dependencies WHERE task_id=?", (id,)).fetchall()]
        for dep in deps:
            row = self._db.execute("SELECT status FROM tasks WHERE id=?", (dep,)).fetchone()
            if row is None or row[0] != "done":
                return False
        return True

    def start(self, id):
        self.get(id)
        try:
            self._db.execute("BEGIN IMMEDIATE")
            cur = self._db.execute("SELECT status FROM tasks WHERE id=?", (id,)).fetchone()[0]
            if cur != "pending":
                raise ValueError("cannot start task in status %s" % cur)
            if not self._deps_done(id):
                raise ValueError("dependencies are not done")
            self._db.execute("UPDATE tasks SET status='running' WHERE id=?", (id,))
            self._db.execute("INSERT INTO events(task_id,action,payload) VALUES(?,?,?)", (id, "start", None))
            self._db.execute("COMMIT")
        except Exception:
            self._db.execute("ROLLBACK")
            raise

    def complete(self, id):
        self.get(id)
        try:
            self._db.execute("BEGIN IMMEDIATE")
